#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int MOD1 = 998244353;
const int MOD2 = 1000000007;
const int BASE = 1000000;

int n, total, sumArr[15], answer;
vector<int> buckets[15];

void generateSequences(int depth, int currentNumber) {
    if (depth == 7) return;
    total++;
    int val = ((total - currentNumber) % MOD1 + MOD1) % MOD1;
    buckets[depth].push_back(val);
    sumArr[depth] = (sumArr[depth] + val) % MOD2;
    for (int digit = 0; digit <= 9; ++digit) {
        generateSequences(depth + 1, currentNumber * 10 + digit);
    }
}

void processNumber(int x) {
    if (x > n) return;
    if (x * BASE + BASE - 1 <= n && x * BASE * 10 > n) {
        int currentTotal = total;
        for (int i = 0, multiplier = 1; i <= 6; ++i, multiplier *= 10) {
            int size = (int)buckets[i].size();
            int diffVal = ((currentTotal - x * multiplier) % MOD1 + MOD1) % MOD1;
            int position = (int)(lower_bound(buckets[i].begin(), buckets[i].end(), (int)(MOD1 - diffVal)) - buckets[i].begin());
            answer = (answer + diffVal * size + sumArr[i]) % MOD2;
            answer = (answer - (long long)MOD1 * (size - position) % MOD2 + MOD2) % MOD2;
            total += size;
        }
        return;
    }
    total++;
    answer = (answer + ((total - x) % MOD1 + MOD1) % MOD1) % MOD2;
    for (int digit = 0; digit <= 9; ++digit) {
        processNumber(x * 10 + digit);
    }
}

int main() {
    cin >> n;
    generateSequences(0, 0);
    for (int i = 0; i <= 7; ++i) {
        sort(buckets[i].begin(), buckets[i].end());
    }
    total = 0;
    for (int i = 1; i <= 9; ++i) {
        processNumber(i);
    }
    cout << answer << endl;
    return 0;
}
